<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class UpbringingNotifications extends Page{protected static ?string $navigationIcon='heroicon-o-bell';protected static ?string $navigationLabel='Уведомления';protected static ?string $navigationGroup='Воспитательная работа';protected static string $view='filament.pages.upbringing-notifications';public array $rows=[];public function mount():void{$this->syncDue();$this->rows=DB::table('upbringing_notifications')->where('user_id',auth()->id())->orderByRaw('read_at is not null')->orderByDesc('created_at')->limit(100)->get()->map(fn($x)=>(array)$x)->all();}private function syncDue():void{$p=request()->attributes->get('academic_period');if(!$p)return;$uid=auth()->id();$tasks=DB::table('upbringing_tasks')->where(['academic_period_id'=>$p->id,'assigned_to'=>$uid])->whereNotIn('status',['done','cancelled'])->whereNotNull('due_on')->where('due_on','<=',now()->addDays(3)->toDateString())->get();foreach($tasks as $x)DB::table('upbringing_notifications')->updateOrInsert(['fingerprint'=>'task-'.$x->id.'-'.$x->due_on],['user_id'=>$uid,'type'=>'task','title'=>'Поручение: '.$x->title,'message'=>'Срок: '.$x->due_on,'url'=>'/admin/upbringing-tasks','updated_at'=>now(),'created_at'=>now()]);$cases=DB::table('student_support_cases')->where(['academic_period_id'=>$p->id,'responsible_user_id'=>$uid])->where('status','!=','closed')->whereNotNull('next_contact_on')->where('next_contact_on','<=',now()->addDays(2)->toDateString())->get();foreach($cases as $x)DB::table('upbringing_notifications')->updateOrInsert(['fingerprint'=>'case-'.$x->id.'-'.$x->next_contact_on],['user_id'=>$uid,'type'=>'case','title'=>'Контроль сопровождения','message'=>'Контрольная дата: '.$x->next_contact_on,'url'=>'/admin/student-support-cases/'.$x->id.'/edit','updated_at'=>now(),'created_at'=>now()]);}public function markRead($id):void{DB::table('upbringing_notifications')->where(['id'=>$id,'user_id'=>auth()->id()])->update(['read_at'=>now(),'updated_at'=>now()]);$this->mount();}public static function canAccess():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->canDo('upbringing.view'));}}